import os, sys, zipfile, re
import xml.etree.ElementTree as ET

path = 'budget.xlsx'
print("exists:", os.path.exists(path))
print("size:", os.path.getsize(path) if os.path.exists(path) else None)

with open(path, 'rb') as f:
    head = f.read(16)
print("header:", head)

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1

if head[:2] == b'PK':
    z = zipfile.ZipFile(path)
    print("zip entries:", [n for n in z.namelist() if 'sheet' in n.lower() or 'workbook' in n.lower() or 'shared' in n.lower()])
    wbxml = z.read('xl/workbook.xml')
    wbroot = ET.fromstring(wbxml)
    sheets = wbroot.findall('.//m:sheet', NS)
    sheet_names = [(s.get('name'), s.get('sheetId'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')) for s in sheets]
    print("sheets:", sheet_names)

    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    RNS = {'r': 'http://schemas.openxmlformats.org/package/2006/relationships'}
    relmap = {}
    for r in rels.findall('r:Relationship', RNS):
        relmap[r.get('Id')] = r.get('Target')

    shared = {}
    if 'xl/sharedStrings.xml' in z.namelist():
        sroot = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for i, si in enumerate(sroot.findall('m:si', NS)):
            texts = si.findall('.//m:t', NS)
            shared[i] = ''.join(t.text or '' for t in texts)

    for name, sid, rid in sheet_names:
        target = relmap.get(rid, '')
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        sxml = z.read(target)
        sroot = ET.fromstring(sxml)
        print(f"\n--- Sheet: {name} ({target}) ---")
        rows = {}
        for c in sroot.findall('.//m:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            if v is not None and v.text is not None:
                val = v.text
            else:
                isel = c.find('m:is', NS)
                if isel is not None:
                    val = ''.join(t.text or '' for t in isel.findall('.//m:t', NS))
                else:
                    val = None
            if t == 's' and val is not None:
                val = shared.get(int(val), '')
            elif t == 'b':
                val = val == '1'
            elif t == 'inlineStr':
                pass
            rows[ref] = val
        for ref in sorted(rows.keys(), key=lambda r: (int(re.match(r'[A-Z]+(\d+)', r).group(1)), col_to_idx(r))):
            print(f"{ref}: {rows[ref]!r}")
else:
    text = open(path, 'r', encoding='utf-8', errors='replace').read()
    print("text content:\n", text[:4000])

