relmap = {r.get('Id'): r.get('Target') for r in rels.findall('r:Relationship', RNS)}
wbroot = ET.fromstring(z.read('xl/workbook.xml'))
s = wbroot.findall('.//m:sheet', NS)[0]
target = relmap[s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')].lstrip('/')
