shared = {}
if 'xl/sharedStrings.xml' in z.namelist():
    ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for i, si in enumerate(ss.findall('m:si', NS)):
        shared[i] = ''.join(t.text or '' for t in si.findall('.//m:t', NS))

cells = {}
for c in sroot.findall('.//m:c', NS):
    ref = c.get('r')
    v = c.find('m:v', NS)
    val = v.text if v is not None and v.text is not None else None
    if c.get('t') == 's' and val is not None:
        val = shared.get(int(val), '')
    cells[ref] = val

total = 0
details = []
for row in range(11, 23):
    cat = cells.get(f'A{row}', '')
    item = cells.get(f'B{row}', '')
    amt = cells.get(f'C{row}')
    val = float(amt) if amt is not None and amt not in ('', None) else 0.0
    total += val
    details.append((cat, item, amt, val))
for d in details:
    print(d)
print("TOTAL_EXPENSES:", total)

